      "id": 19,
      "title": "Capítulo 19: Muro de Lorentz",
      "act": "Acto III: El Silencio",
      "pov": "James MacElroy / Alexei Voronov / Chen Mei",
      "location": "Crucero interplanetario a L1 / Perímetro de seguridad a 12.000 km",
      "readTime": "16 min",
      "povImage": "img/char_protagonista.png",
